import "core-js/modules/es6.function.name";
import "core-js/modules/es6.array.find";
import { getList as _getList, refresh } from "@/api/data/erp/cbcenter";
import { erpUnitList } from "@/api/system/dept";
import SwerkRefresh from "@/views/data/components/erp/components/swerkRefresh.vue";
import projectRefresh from "@/views/assets/components/projectManage/projectRefresh.vue";
import Cbdetial from "@/views/data/components/erp/components/cbdetial.vue";
//成本中心页面
export default {
  name: 'chengben_center',
  components: {
    Cbdetial: Cbdetial,
    projectRefresh: projectRefresh,
    SwerkRefresh: SwerkRefresh
  },
  data: function data() {
    return {
      tbloading: false,
      tableloading: false,
      queryParams: {},
      page: {
        currentPage: 1,
        pageSize: 20,
        total: 0
      },
      tableData: null,
      erpUnits: null,
      showSync: false,
      statusList: null,
      showDetial: false,
      fromValue: null
    };
  },
  mounted: function mounted() {
    this.page = {
      currentPage: 1,
      pageSize: 20,
      total: 0
    };
    this.getDict();
    this.getList();
  },
  methods: {
    // 字典
    getDict: function getDict() {
      var _this = this;
      erpUnitList().then(function (res) {
        _this.erpUnits = res.data;
      });
      this.statusList = [{
        name: '正常',
        code: 0
      }, {
        name: '异常',
        code: -1
      }];
    },
    getList: function getList() {
      var _this2 = this;
      this.tableloading = true;
      _getList(this.page.currentPage, this.page.pageSize, this.queryParams).then(function (res) {
        var data = res.data;
        _this2.page.total = data.total;
        _this2.tableData = data.records;
        _this2.tableloading = false;
      });
    },
    handelRefresh: function handelRefresh() {
      this.showSync = true;
    },
    handleDetial: function handleDetial(row) {
      this.fromValue = row;
      this.showDetial = true;
    },
    getRefresh: function getRefresh(arg) {
      var _this3 = this;
      this.showSync = false;
      this.tbloading = true;
      refresh({
        swerk: arg.swerk
      }).then(function (res) {
        _this3.getList();
        _this3.$message.success('同步成功');
      }).finally(function () {
        _this3.tbloading = false;
      });
    },
    Nindex: function Nindex(index) {
      return index + 1 + (this.page.currentPage - 1) * this.page.pageSize;
    },
    reset: function reset() {
      this.queryParams = {};
      this.page = {
        currentPage: 1,
        pageSize: 20,
        total: 0
      };
      this.getList();
    },
    getSwerkName: function getSwerkName(swerk) {
      if (swerk && this.erpUnits) {
        var fItem = this.erpUnits.find(function (a) {
          return a.code == swerk;
        });
        if (fItem) {
          return fItem.name;
        }
      }
      return null;
    },
    getStatusColor: function getStatusColor(status) {
      if (status == '0') {
        return '#229241';
      }
      return '#E63E31';
    },
    getStatusName: function getStatusName(status) {
      if (status == '0') {
        return '正常';
      }
      return '异常';
    }
  }
};
